import json
import sys


def extract_fields(payload):
    """Extract exact, case-sensitive labels from colon-delimited lines.

    Labels must match exactly before the first colon. Values have surrounding
    whitespace removed. Ignore unrequested labels and lines without a colon.
    Omit absent fields; reject repeated requested labels, even if values agree.
    """
    invalid = {"error": "invalid_input"}
    if not isinstance(payload, dict) or set(payload) != {"text", "fields"}:
        return invalid
    text = payload["text"]
    fields = payload["fields"]
    if not isinstance(text, str) or len(text) > 100000:
        return invalid
    if not isinstance(fields, list) or not 1 <= len(fields) <= 100:
        return invalid
    if any(not isinstance(field, str) for field in fields):
        return invalid
    requested = set(fields)
    if len(requested) != len(fields):
        return invalid

    found = {}
    for line in text.splitlines():
        label, separator, value = line.partition(":")
        if not separator or label not in requested:
            continue
        if label in found:
            return invalid
        found[label] = value.strip()
    return {"fields": {field: found[field] for field in fields if field in found}}


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate JSON key")
        result[key] = value
    return result


def _reject_constant(value):
    raise ValueError("Invalid JSON constant")


def main():
    try:
        payload = json.loads(
            sys.stdin.buffer.read().decode("utf-8"),
            object_pairs_hook=_unique_object,
            parse_constant=_reject_constant,
        )
        result = extract_fields(payload)
    except (ValueError, RecursionError):
        result = {"error": "invalid_input"}
    sys.stdout.buffer.write(
        (json.dumps(result, ensure_ascii=True) + "\n").encode("utf-8")
    )


if __name__ == "__main__":
    main()
